/// <summary>
/// ReturnOrderLineEntity COC class
/// </summary>
[ExtensionOf(tableStr(ReturnOrderLineEntity))]
final class METReturnOrderLineEntity_Extension
{
}

Method.Source:
/// <summary>
/// MPJ_24809 Returns Claims
/// </summary>
/// <returns>boolean</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();
    if(this.METInvoiceNumber && this.METInvoiceLineNumber)
    {
        CustInvoiceTrans    metCustInvoiceTransStd;
        select firstonly metCustInvoiceTransStd
            where metCustInvoiceTransStd.InvoiceId  == this.METInvoiceNumber &&
                  metCustInvoiceTransStd.LineNum    == this.METInvoiceLineNumber;
        if(metCustInvoiceTransStd)
        {                
            if(metCustInvoiceTransStd.SalesUnit != this.SalesUnitSymbol)//MPJ-35503-Broken cases
            {                    
                METSalesLine    metSalesLine;
                SalesLine       metSalesLineStd;                
                select firstonly RecId from metSalesLine                        
                    exists Join metSalesLineStd
                    where metSalesLine.InvoiceNumber        == this.METInvoiceNumber &&
                          metSalesLine.InvoiceLineNumber    == this.METInvoiceLineNumber &&
                          metSalesLineStd.RecId             == metSalesLine.SalesLine &&
                          metSalesLineStd.SalesId           == this.ReturnOrderNumber;
                          
                if(metSalesLine.RecId)
                {
                    ret = ret && checkFailed("@MET:ReturnLineForThisInvoiceLineAlreadyExist");
                }
            }
            
        }
        else
        {
            ret = checkFailed("@PSA10213");
        }
    }
    return ret;
}

/// <summary>
/// MPJ_24809 Returns Claims
/// </summary>    
public void insert()
{
    
    CustInvoiceTrans    metCustInvoiceTransStd;
    select firstonly metCustInvoiceTransStd
        where metCustInvoiceTransStd.InvoiceId  == this.METInvoiceNumber &&
              metCustInvoiceTransStd.LineNum    == this.METInvoiceLineNumber;
    if(metCustInvoiceTransStd)
    {
        if(metCustInvoiceTransStd.SalesUnit == this.SalesUnitSymbol)
        {
            this.SalesPrice         = metCustInvoiceTransStd.SalesPrice;
            this.SalesUnitSymbol    = metCustInvoiceTransStd.SalesUnit;
        }
        else //MPJ-35503-Broken cases
        {
            this.METBrokenCaseForClaims = NoYes::Yes;
            if(metCustInvoiceTransStd.SalesUnit == this.SalesUnitSymbol)
            {
                this.SalesPrice             = metCustInvoiceTransStd.SalesPrice;
            }
            else 
            {
                this.SalesPrice             = metCustInvoiceTransStd.SalesPrice/UnitOfMeasureConverter::convert(1,
               UnitOfMeasure::unitOfMeasureIdBySymbol(metCustInvoiceTransStd.SalesUnit),
               UnitOfMeasure::unitOfMeasureIdBySymbol(this.SalesUnitSymbol),
               NoYes::Yes,
               InventTable::itemProduct(this.ItemNumber),
               NoYes::Yes);
            
            }
        }
        this.LineAmount             = -(metCustInvoiceTransStd.LineAmount);
        this.ReturnSiteId           = metCustInvoiceTransStd.inventSiteId();
        this.ReturnWarehouseId      = metCustInvoiceTransStd.inventLocationId();
        this.ReturnInventoryLotId   = metCustInvoiceTransStd.InventTransId;
        this.METInventTransIdReturn = metCustInvoiceTransStd.InventTransId;
        //Catch weight item
        if (InventTable::find(this.ItemNumber).Product().PdsCWProduct)
        {
            this.METPdsCWQty=-1;
        }
    }
    next insert();
}

/// <summary>
/// CoC method for InsertEntityDataSource method
/// </summary>
/// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
/// <returns>true of false</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(ReturnOrderLineEntity, METSalesLine))
    {
        SalesLine salesLine = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(ReturnOrderLineEntity, SalesLine)).getBuffer();
        _dataSourceCtx.setBuffer(METSalesLine::find(SalesLine.RecId, true));
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
        this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
    }
    
    boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    return ret;
}

    /// <summary>
    /// Finds record buffer for data source and return
    /// </summary>
    /// <param name = "_entityCtx">Entity context</param>
    /// <param name = "_dataSourceCtx">Data source runtime context</param>
    /// <returns>Record buffer associated with data source</returns>
    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataEntityDataSourceStr(ReturnOrderLineEntity, METSalesLine))
        {
            ret = METSalesLine::find(this.RecId);
        }

        return ret;
    }
